$ErrorActionPreference = 'Stop'
$root = 'src\editors\website'
if (!(Test-Path (Join-Path $root 'WebsiteEditor.tsx'))) { throw 'Run from the Onyx Studio project root.' }
$utf8 = New-Object System.Text.UTF8Encoding($false)
$changes = @(
  @{ Name = 'websiteTypes.ts'; Sha = 'F07F20B327234F4BCB903C532FA2ED9BFAB7EBF52A0FAC3EE3D868C990F0589C'; Data = '' }
  @{ Name = 'WebsiteEditor.tsx'; Sha = '3565F144D238197900130F34EC96A45272137AAF5D1EBD15FAB98E47FF7E5A9E'; Data = '' }
  @{ Name = 'websiteExporter.ts'; Sha = 'F4BA47EF95623A58B8EEE823123F1B2B18A3EAAF58F1D959E83AE60086741EBF'; Data = '' }
  @{ Name = 'WebsiteStyleInspector.tsx'; Sha = ''; Data = '' }
)
foreach ($item in $changes) {
  $file = Join-Path $root $item.Name
  if ($item.Sha -ne '') {
    if (!(Test-Path $file)) { throw "Missing $file" }
    $actual = (Get-FileHash -Algorithm SHA256 $file).Hash
    if ($actual -ne $item.Sha) { throw "Local file differs from uploaded $($item.Name). No changes made. Upload the current version for a tailored patch." }
  } elseif (Test-Path $file) {
    throw "New inspector file already exists: $file. No changes made."
  }
}
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backups = @()
try {
  foreach ($item in $changes) {
    $file = Join-Path $root $item.Name
    if (Test-Path $file) {
      $backup = "$file.$stamp.bak"
      Copy-Item $file $backup
      $backups += @{ File = $file; Backup = $backup }
    }
    [System.IO.File]::WriteAllBytes((Join-Path (Get-Location).Path $file), [Convert]::FromBase64String($item.Data))
    Write-Host "Updated $file"
  }
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
  Write-Host 'Website appearance controls installed and build passed!' -ForegroundColor Green
} catch {
  foreach ($item in $backups) { Copy-Item $item.Backup $item.File -Force }
  $newFile = Join-Path $root 'WebsiteStyleInspector.tsx'
  if (Test-Path $newFile) { Remove-Item $newFile -Force }
  Write-Host 'Restored backups after failure.' -ForegroundColor Yellow
  throw
}
